30	  public all() {
31	    const listener = (event: { data: { result: void | [number, T] } }) => {
32	      if (event.data.result) {
33	        // by default pool does not return the results, so we are gathering them manually
34	        // with the correct call order (represented by the index in the tuple)
35	        const [index, value] = event.data.result;
